import React from 'react';
import { User, MapPin, Award, TrendingUp, Calendar, Shield, Mail } from 'lucide-react';
import { getCurrentUser } from '../utils/auth';

function Profile() {
  const user = getCurrentUser() || {
    name: 'Guest User',
    email: 'guest@example.com',
    location: 'Unknown',
    role: 'user',
    joinDate: new Date().toISOString(),
    stats: {
      totalReports: 0,
      resolvedIssues: 0,
      points: 0,
      rank: 0
    }
  };

  const recentActivity = [
    { action: 'Reported', issue: 'Broken streetlight', date: '2024-01-20' },
    { action: 'Resolved', issue: 'Pothole on MG Road', date: '2024-01-18' },
    { action: 'Upvoted', issue: 'Water supply issue', date: '2024-01-15' }
  ];

  return (
    <div style={{ maxWidth: '900px', margin: '0 auto', padding: '20px' }}>
      <h1 style={{ 
        fontSize: '28px', 
        fontWeight: '700', 
        color: '#000080',
        marginBottom: '30px'
      }}>
        My Profile
      </h1>

      {/* Profile Card */}
      <div style={{
        backgroundColor: 'white',
        borderRadius: '16px',
        padding: '30px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        marginBottom: '30px'
      }}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '20px',
          marginBottom: '20px'
        }}>
          <div style={{
            width: '80px',
            height: '80px',
            borderRadius: '50%',
            backgroundColor: '#FF9933',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            fontSize: '32px',
            fontWeight: '700'
          }}>
            {user.name.charAt(0)}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
              marginBottom: '8px'
            }}>
              <h2 style={{
                fontSize: '24px',
                fontWeight: '700',
                color: '#000080',
                margin: 0
              }}>
                {user.name}
              </h2>
              {user.role === 'admin' && (
                <span style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '5px',
                  padding: '4px 12px',
                  backgroundColor: '#000080',
                  color: 'white',
                  borderRadius: '20px',
                  fontSize: '12px',
                  fontWeight: '600'
                }}>
                  <Shield size={14} />
                  ADMIN
                </span>
              )}
            </div>
            <p style={{
              display: 'flex',
              alignItems: 'center',
              gap: '5px',
              color: '#666',
              marginBottom: '5px',
              fontSize: '14px'
            }}>
              <Mail size={16} />
              {user.email}
            </p>
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '5px'
            }}>
              <p style={{
                display: 'flex',
                alignItems: 'center',
                gap: '5px',
                color: '#666',
                fontSize: '14px',
                margin: 0
              }}>
                <MapPin size={16} />
                {user.location}
              </p>
              {user.area && (
                <p style={{
                  fontSize: '13px',
                  color: '#999',
                  margin: 0,
                  paddingLeft: '21px'
                }}>
                  {user.area} {user.pincode && `• ${user.pincode}`}
                </p>
              )}
            </div>
          </div>
        </div>

        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '5px',
          color: '#666',
          fontSize: '14px',
          paddingTop: '15px',
          borderTop: '1px solid #F0F0F0'
        }}>
          <Calendar size={16} />
          Member since {new Date(user.joinDate).toLocaleDateString('en-IN', {
            month: 'long',
            year: 'numeric'
          })}
        </div>
      </div>

      {/* Stats Grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
        gap: '20px',
        marginBottom: '30px'
      }}>
        <div style={{
          backgroundColor: 'white',
          borderRadius: '16px',
          padding: '20px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: '#FF9933',
            marginBottom: '5px'
          }}>
            {user.stats.totalReports}
          </div>
          <div style={{ color: '#666', fontSize: '14px' }}>
            Total Reports
          </div>
        </div>

        <div style={{
          backgroundColor: 'white',
          borderRadius: '16px',
          padding: '20px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: '#138808',
            marginBottom: '5px'
          }}>
            {user.stats.resolvedIssues}
          </div>
          <div style={{ color: '#666', fontSize: '14px' }}>
            Resolved Issues
          </div>
        </div>

        <div style={{
          backgroundColor: 'white',
          borderRadius: '16px',
          padding: '20px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: '#000080',
            marginBottom: '5px'
          }}>
            {user.stats.points}
          </div>
          <div style={{ color: '#666', fontSize: '14px' }}>
            Total Points
          </div>
        </div>

        <div style={{
          backgroundColor: 'white',
          borderRadius: '16px',
          padding: '20px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: '#FFD700',
            marginBottom: '5px'
          }}>
            #{user.stats.rank}
          </div>
          <div style={{ color: '#666', fontSize: '14px' }}>
            Community Rank
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div style={{
        backgroundColor: 'white',
        borderRadius: '16px',
        padding: '30px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
      }}>
        <h3 style={{
          fontSize: '20px',
          fontWeight: '600',
          color: '#000080',
          marginBottom: '20px'
        }}>
          Recent Activity
        </h3>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {recentActivity.map((activity, index) => (
            <div
              key={index}
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '15px',
                backgroundColor: '#F9F9F9',
                borderRadius: '8px'
              }}
            >
              <div>
                <span style={{ fontWeight: '600', color: '#FF9933' }}>
                  {activity.action}
                </span>
                {' '}
                <span style={{ color: '#666' }}>
                  {activity.issue}
                </span>
              </div>
              <span style={{ fontSize: '14px', color: '#999' }}>
                {new Date(activity.date).toLocaleDateString('en-IN', {
                  day: 'numeric',
                  month: 'short'
                })}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Profile;
